// Arquivos estáticos importados pelo Vite viram a URL final do arquivo.
declare module "*.png" {
  const url: string;
  export default url;
}
declare module "*.ogg" {
  const url: string;
  export default url;
}
declare module "*.mp3" {
  const url: string;
  export default url;
}
declare module "*.webp" {
  const url: string;
  export default url;
}
